const EMM_BANK_B64='';
const EMM_META=[
 ['FUNK BASS','bass funk punchy plucked deep sequenced'],['STRINGBELL','string bell chime hollow evolving wash hybrid'],['GRANDBRASS','grand brass ensemble guitar piano powerful'],['WURLITZER','wurlitzer electric piano tine touch sensitive dynamic'],['SPLT KYBRD','split keyboard dual layered crossover'],['FUNKMASTER','funk twang thump clavinet plucked bass metallic silky'],['SYNTH FULL','full synth muted strident penetrating brassy expressive'],['SYN-PHIZZ','lead full organ brass portamento sustained'],['HONKIGRAND','honky grand old piano broken acoustic'],['BRASS-SOLO','brass solo expressive wheel aftertouch'],['FUNK BASS','funk bass punchy sequenced bright vibrato'],['RESIN BASS','resin bass bowed bite strong orchestral'],['FIZZ BUZZ','fizzy buzzy beefy aggressive hard synth'],['FAIRLIGHT','fairlight nasal breathy piercing delicate thin'],['SLAPS','slap piano harpsichord distorted electric piano'],['MORTHNGRND','grand piano warm delicate aggressive rock dynamic'],['REAL GRAND','real grand sweet acoustic piano classical'],['TIMEFLUSS','flutey brass expressive muted modulation'],['BERLIN','warm analog bass cinematic soft'],['SYNSCNARIO','synth flute organ chiff swell intriguing'],['MARVIN','guitar solo chordal pitch bend modulation'],['AXE','screaming guitar aggressive solo pitch bend'],['SOFT STRGS','soft warm analog strings emotive background'],['CURVED AIR','deep massed vocal choir eerie mutated low'],['NOBODYELSE','warm fuzzy analog full solo synth'],['STRUNGOUT','deep dramatic strings impact foreground'],['TIGHT BASS','tight minimoog bass focused brittle metallic stab'],['ANGELGLASS','angel glass glossy transparent delicate atmospheric bell']
];
function decodeEmmBank(){const raw=Uint8Array.from(atob(EMM_BANK_B64),c=>c.charCodeAt(0)),data=raw.slice(6,-2);return EMM_META.map((m,s)=>{const d=data.slice(s*128,(s+1)*128),ops=[];for(let stored=0;stored<6;stored++){const q=d.slice(stored*17,stored*17+17),mode=q[15]&1,coarse=(q[15]>>1)&31,fine=q[16];ops.push({rates:[...q.slice(0,4)],levels:[...q.slice(4,8)],breakpoint:q[8],leftdepth:q[9],rightdepth:q[10],leftcurve:q[11]&3,rightcurve:(q[11]>>2)&3,ratescale:q[12]&7,detune:(q[12]>>3)&15,ams:q[13]&3,vel:(q[13]>>2)&7,level:q[14],mode,ratio:coarse||.5,fixed:mode?Math.pow(10,coarse):440,fine,carrier:false})}return{name:m[0],words:m[1].split(' '),ops,algorithm:d[110],feedback:d[111]&7,transpose:d[117],lfo:{speed:d[112],delay:d[113],pmd:d[114],amd:d[115],sync:d[116]&1,wave:(d[116]>>1)&7,pms:(d[116]>>4)&7}}})}
const EMM_VOICES=decodeEmmBank();
function emmForgeVoice(autoVary=false){let variation=+$('#seed').value,text=$('#prompt').value.trim(),lower=text.toLowerCase(),signature=text+'|'+variation;if(autoVary&&signature===lastSignature){variation=variation%99+1;$('#seed').value=variation;$('#seedOut').value=variation}lastSignature=text+'|'+variation;const t=analyse(text),scored=EMM_VOICES.map((v,i)=>({v,i,score:v.words.reduce((n,w)=>n+(lower.includes(w)?w.length+5:0),0)}));scored.sort((a,b)=>b.score-a.score||a.i-b.i);let base=scored[0];if(!base.score){const fallback={bass:26,bell:1,pad:22,strings:22,ep:3,brass:9,lead:6,choir:23,pluck:5,mallet:14,organ:19};base={v:EMM_VOICES[fallback[t.family]??6],i:fallback[t.family]??6,score:1}}const v=structuredClone(base.v),hits=[...new Set([...t.hits,...v.words.filter(w=>lower.includes(w))])],bright=/bright|strident|penetrating|cutting|hard|metallic|glossy|fizzy|buzzy/.test(lower),warm=/warm|soft|mellow|gentle|delicate/.test(lower),long=/long|lingering|sustain|wash|atmospheric|slow/.test(lower),short=/short|tight|staccato|snappy|pluck|percussive/.test(lower),moving=/evolving|bloom|swell|animated|movement|shimmer|vibrato/.test(lower),stable=/stable|pure|focused|clean/.test(lower),dynamic=/expressive|responsive|touch|dynamic|velocity/.test(lower),r=rng(hash(text)+variation),amount=(variation-50)/49;
  v.ops.forEach((o,i)=>{const spectral=o.ratio>=3||o.fine>10;o.level=clamp(o.level+(spectral&&bright?5:0)-(spectral&&warm?5:0)+amount*2+(r()-.5)*2,0,99);if(long){o.rates[1]=clamp(o.rates[1]-7,0,99);o.rates[3]=clamp(o.rates[3]-8,0,99)}if(short){o.rates[1]=clamp(o.rates[1]+7,0,99);o.rates[3]=clamp(o.rates[3]+8,0,99)}if(moving&&i%2===0)o.rates[0]=clamp(o.rates[0]-8,0,99);if(stable){o.fine=o.fine<=3?0:o.fine;o.detune=7+Math.round((o.detune-7)*.6)}if(dynamic&&spectral)o.vel=clamp(o.vel+1,0,7)});
  if(base.i===5){if(warm)v.ops[1].level=73;if(bright)v.ops[1].level=83;if(/cutting|hard/.test(lower))v.ops[1].level=92}if(base.i===6&&stable){v.ops[4].fine=0;v.ops[0].fine=0}if(base.i===27){if(short)v.ops[2].rates[3]=28;if(/strong|powerful/.test(lower)){v.ops[5].level=98;v.ops[2].level=99}}if(base.i===1&&/octave up|higher|bright/.test(lower))v.transpose=clamp(v.transpose+12,0,48);
  if(moving){v.lfo.pmd=clamp(v.lfo.pmd+8,0,99);v.lfo.delay=clamp(v.lfo.delay+10,0,99)}if(warm)v.feedback=clamp(v.feedback-1,0,7);if(bright)v.feedback=clamp(v.feedback+1,0,7);v.name=(v.name.replace(/[^A-Z0-9]/g,'').slice(0,7)+String(variation).padStart(2,'0')).slice(0,10);const current=$('#patchName').value.trim(),previous=voice?.name.trim();if(!voice||current===previous)$('#patchName').value=v.name;voice={...v,name:($('#patchName').value||v.name).trim().toUpperCase().slice(0,10),variation,t:{...t,hits,family:v.name.toLowerCase()}};render()}
const baseSsynthParameters=ssynthParameters;ssynthParameters=function(){const p=baseSsynthParameters();for(let n=1;n<=6;n++){const o=voice.ops[6-n],x=`fm80op${n}`;p[x+'mode']=o.mode??0;p[x+'fixed']=o.fixed??440;p[x+'fine']=o.fine??0;p[x+'breakpoint']=o.breakpoint??39;p[x+'leftdepth']=o.leftdepth??0;p[x+'rightdepth']=o.rightdepth??0;p[x+'leftcurve']=o.leftcurve??0;p[x+'rightcurve']=o.rightcurve??0;p[x+'ratescale']=o.ratescale??0;p[x+'ams']=o.ams??0}return p};
$('#generate').onclick=()=>emmForgeVoice(true);document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{$('#prompt').value=b.dataset.prompt;emmForgeVoice()});emmForgeVoice();
